 "standings_eligible": true, "profile_version": 2, "updated_at": "2026-10-15T23:26:43.401924+00:00"}, {"id": "8f0b3cd6-a819-411e-b08c-b57a3c9367fe", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "legacy_id": "wed-rinnai", "name": "Rinnai", "status": "active", "kit_colour": "#1E66E5", "standings_eligible": true, "profile_version": 2, "updated_at": "2026-10-13T01:59:21.938786+00:00"}, {"id": "bafe147f-c3ac-4285-8159-f8e13a06e067", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "legacy_id": "wed-umoja-stars", "name": "Umoja Stars", "status": "active", "kit_colour": "#111111", "standings_eligible": true, "profile_version": 2, "updated_at": "2026-10-13T01:59:21.938786+00:00"}, {"id": "9d563647-382e-405b-a34d-5912e8b34791", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "legacy_id": "wed-unathletico", "name": "Unathletico", "status": "withdrawn", "kit_colour": "#F2994A", "standings_eligible": false, "profile_version": 2, "updated_at": "2026-10-15T08:58:03.138018+00:00"}, {"id": "a7306808-977f-496c-8f6c-3141529ca76c", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "legacy_id": "wed-wildcats", "name": "Wildcats", "status": "active", "kit_colour": "#F2D34F", "standings_eligible": true, "profile_version": 2, "updated_at": "2026-10-13T01:59:21.938786+00:00"}, {"id": "435af587-f6ea-5030-a097-94ad466481c2", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "legacy_id": "wed-xaywan", "name": "Xaywan", "status": "active", "kit_colour": null, "standings_eligible": true, "profile_version": 1, "updated_at": "2026-10-15T08:58:03.138018+00:00"}]'::jsonb);
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM n18_team_baseline b LEFT JOIN public.teams t USING(id) WHERE row(b.competition_season_id,b.legacy_id,b.name,b.status,b.kit_colour,b.standings_eligible,b.profile_version,b.updated_at) IS DISTINCT FROM row(t.competition_season_id,t.legacy_id,t.name,t.status,t.kit_colour,t.standings_eligible,t.profile_version,t.updated_at)) THEN RAISE EXCEPTION 'Team profile baseline changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='be008d39-f175-45c1-a232-2148d84b1cf9' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition state changed';END IF;
 IF (SELECT count(*) FROM n18_baseline)<>11 OR EXISTS(SELECT 1 FROM n18_baseline b LEFT JOIN public.fixtures f USING(id) WHERE row(b.competition_season_id,b.round_number,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.schedule_version,b.updated_at,b.publication_state,b.schedule_status,b.stage) IS DISTINCT FROM row(f.competition_season_id,f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.schedule_version,f.updated_at,f.publication_state,f.schedule_status,f.stage) OR f.match_date<'2026-11-18') THEN RAISE EXCEPTION 'Fixture baseline changed or already applied';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM n18_baseline)) THEN RAISE EXCEPTION 'Result work exists';END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Pending fixture plan';END IF;
END $$;
UPDATE public.fixtures f SET home_team_id=p.home_team_id,away_team_id=p.away_team_id FROM n18_target p WHERE p.id=f.id;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM n18_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE CASE WHEN b.id IN(SELECT id FROM n18_target) THEN
 (to_jsonb(b)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(f)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at') OR f.schedule_version<>b.schedule_version+1 OR NOT EXISTS(SELECT 1 FROM n18_target p WHERE p.id=f.id AND row(p.home_team_id,p.away_team_id)=row(f.home_team_id,f.away_team_id))
 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(f) END) THEN RAISE EXCEPTION 'Unexpected fixture change';END IF;
 IF EXISTS(SELECT 1 FROM n18_results_before b FULL JOIN public.result_versions t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Results changed';END IF;
 IF EXISTS(SELECT 1 FROM n18_teams_before b FULL JOIN public.teams t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Teams changed';END IF;
 IF EXISTS(SELECT 1 FROM n18_notes_before b FULL JOIN public.team_fixture_notes t USING(team_id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Notes changed';END IF;
 IF EXISTS(SELECT 1 FROM n18_preferences_before b FULL JOIN public.team_kickoff_preferences t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Preferences changed';END IF;
 IF EXISTS(SELECT 1 FROM n18_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
 IF (SELECT count(*)FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled')<>240 THEN RAISE EXCEPTION 'Fixture total failed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled' GROUP BY least(home_team_id,away_team_id),greatest(home_team_id,away_team_id) HAVING count(*)<>2 OR count(DISTINCT home_team_id)<>2) THEN RAISE EXCEPTION 'Pair counts or home-away failed';END IF;
 IF EXISTS(SELECT round_number,team_id FROM(SELECT round_number,home_team_id team_id FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled' UNION ALL SELECT round_number,away_team_id FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled')x GROUP BY round_number,team_id HAVING count(*)<>1) THEN RAISE EXCEPTION 'Duplicate round appearance';END IF;
END $$;
SELECT txid_current() AS transaction_id,(SELECT count(*) FROM n18_target) AS changed_fixtures;
COMMIT;
